  const [confirmPassword, setConfirmPassword] = useState("");
  const mutation = useMutation({ mutationFn: () => apiPost<User>("/auth/register", { username, password, role: "VIEWER" }), onSuccess: () => { toast.success("Account created", { description: "Your VIEWER account is ready. Use LOGIN to enter the SOC." }); onLogin(); }, onError: () => toast.error("Sign in could not be completed", { description: "Choose a unique username and a password with at least 6 characters." }) });
