function URLAnalyzer() {
  const [url, setUrl] = useState("https://example.com");
  const [authorized, setAuthorized] = useState(false);
  const [result, setResult] = useState<URLCheck | null>(null);
  const mutation = useMutation({ mutationFn: () => apiPost<URLCheck>("/url-checks/analyze", { url, authorized }), onSuccess: (data) => { setResult(data); queryClient.invalidateQueries({ queryKey: ["url-checks"] }); queryClient.invalidateQueries({ queryKey: ["dashboard"] }); queryClient.invalidateQueries({ queryKey: ["threats"] }); queryClient.invalidateQueries({ queryKey: ["incidents"] }); queryClient.invalidateQueries({ queryKey: ["audit"] }); toast.success("Passive URL check stored in SOC"); }, onError: () => toast.error("URL check blocked", { description: "Confirm authorization and use a public HTTP/HTTPS URL." }) });
  return <Section title="Passive URL analyzer" eyebrow="AUTHORIZED URL RISK CHECK" className="mt-5" action={<span className="font-mono text-[10px] text-cyan-300/70">ONE BOUNDED FETCH</span>}><div className="grid gap-5 xl:grid-cols-[1fr_0.9fr]"><div><label className="block"><span className="mb-2 block font-mono text-[10px] uppercase tracking-[0.16em] text-slate-500">Website URL</span><Input data-testid="url-analyzer-input" type="url" value={url} onChange={(event) => setUrl(event.target.value)} placeholder="https://example.com" className="h-11 rounded-none border-slate-700 bg-[#080f1b] text-xs text-slate-200" /></label><label className="mt-4 flex cursor-pointer items-start gap-3 border border-yellow-300/20 bg-yellow-300/5 p-3" data-testid="url-authorization-label"><input data-testid="url-authorization-checkbox" type="checkbox" checked={authorized} onChange={(event) => setAuthorized(event.target.checked)} className="mt-0.5 accent-cyan-300" /><span className="text-xs leading-relaxed text-slate-400">I own or am authorized to assess this URL. I understand this performs one passive request only and does not exploit, crawl, or modify the target.</span></label><Button data-testid="url-analyzer-submit-button" type="button" onClick={() => mutation.mutate()} disabled={!authorized || mutation.isPending || !url.trim()} className="mt-4 h-10 rounded-none bg-cyan-300 font-mono text-[10px] font-semibold tracking-[0.13em] text-[#07111d] hover:bg-cyan-200">{mutation.isPending ? "CHECKING PASSIVELY…" : "CHECK URL RISK"}<Globe size={14} /></Button></div><div className={`min-h-[210px] border p-5 ${result?.risk_score && result.risk_score >= 51 ? "border-rose-300/40 bg-rose-300/5" : result ? "border-green-300/30 bg-green-300/5" : "border-slate-800 bg-[#080f1b]"}`} data-testid="url-analyzer-result"><div className="flex items-start justify-between"><div><div className="font-mono text-[10px] tracking-[0.18em] text-slate-500">PASSIVE RISK OUTCOME</div><div className={`mt-3 font-heading text-2xl font-medium ${result?.risk_score && result.risk_score >= 51 ? "text-rose-200" : result ? "text-green-200" : "text-slate-500"}`} data-testid="url-analyzer-classification">{result ? result.classification : "READY TO CHECK"}</div></div><Globe size={23} className={result?.risk_score && result.risk_score >= 51 ? "text-rose-300" : result ? "text-green-300" : "text-slate-600"} /></div>{result ? <><div className="mt-5 grid grid-cols-3 gap-3 border-t border-slate-700/60 pt-4 font-mono text-[10px]"><div><span className="block text-lg text-slate-100">{result.risk_score}</span><span className="text-slate-600">risk score</span></div><div><span className="block text-lg text-slate-100">{result.status_code ?? "—"}</span><span className="text-slate-600">HTTP</span></div><div><span className="block text-lg text-slate-100">{result.redirects}</span><span className="text-slate-600">redirects</span></div></div><div className="mt-4 space-y-1" data-testid="url-analyzer-findings">{result.findings.slice(0, 4).map((finding) => <div key={finding} className="text-xs text-slate-400">• {finding}</div>)}</div></> : <p className="mt-7 text-xs leading-relaxed text-slate-600">Risk indicators include HTTPS, redirect behavior, security headers, suspicious URL structure, and public reachability. A clean result is not proof that a site is safe.</p>}</div></div><div className="mt-4 border border-yellow-300/20 bg-yellow-300/5 p-3 font-mono text-[10px] uppercase tracking-[0.12em] text-yellow-200/75" data-testid="url-analyzer-safety-note"><ShieldCheck size={13} className="mr-2 inline text-yellow-300" /> AUTHORIZED PASSIVE CHECK · NO CRAWLING · NO EXPLOITATION · NO EXTERNAL ACTION</div></Section>;
}

function URLChecksView({ checks }: { checks: URLCheck[] }) {
  return <><PageHeader eyebrow="WEB RISK / PASSIVE INSPECTION" title="URL checks" subtitle="Review authorized, one-request URL risk signals stored in the SOC workflow." /><URLAnalyzer /><Section title="URL check history" eyebrow="PERSISTED SECURITY EVENTS" className="mt-5"><div className="overflow-x-auto" data-testid="url-check-history"><table className="w-full min-w-[720px] text-left"><thead><tr className="border-b border-slate-800 font-mono text-[9px] tracking-[0.16em] text-slate-600"><th className="pb-3">Checked</th><th className="pb-3">URL</th><th className="pb-3">Classification</th><th className="pb-3">Risk</th><th className="pb-3">HTTP</th><th className="pb-3">Reachable</th></tr></thead><tbody>{checks.map((check) => <tr key={check.id} className="border-b border-slate-800/60 text-xs" data-testid={`url-check-row-${check.id}`}><td className="py-3 font-mono text-slate-500">{formatTime(check.checked_at)}</td><td className="max-w-[280px] truncate py-3 font-mono text-cyan-200">{check.url}</td><td className="py-3 text-slate-300">{check.classification}</td><td className="py-3"><Severity value={check.severity} /></td><td className="py-3 font-mono text-slate-400">{check.status_code ?? "—"}</td><td className="py-3 font-mono text-green-300">{check.reachable ? "YES" : "NO"}</td></tr>)}</tbody></table>{checks.length === 0 && <div className="py-12 text-center font-mono text-xs text-slate-600" data-testid="url-check-empty-state">NO URL CHECKS YET · CONFIRM AUTHORIZATION TO BEGIN</div>}</div></Section></>;
}

function ThreatAnalyzer() {
  const [eventType, setEventType] = useState("High-volume Traffic");
  const [sourceIp, setSourceIp] = useState("192.168.1.25");
  const [failedAttempts, setFailedAttempts] = useState("0");
  const [trafficVolume, setTrafficVolume] = useState("1200");
  const [result, setResult] = useState<AnalyzeResult | null>(null);
  const mutation = useMutation({ mutationFn: () => apiPost<AnalyzeResult>("/detection/analyze", { event_type: eventType, source_ip: sourceIp, failed_attempts: Number(failedAttempts), traffic_volume: Number(trafficVolume) }), onSuccess: (data) => { setResult(data); queryClient.invalidateQueries({ queryKey: ["dashboard"] }); queryClient.invalidateQueries({ queryKey: ["threats"] }); queryClient.invalidateQueries({ queryKey: ["incidents"] }); queryClient.invalidateQueries({ queryKey: ["audit"] }); toast.success(data.is_threat ? "Threat persisted to SOC" : "Event classified as normal"); }, onError: () => toast.error("Analysis failed", { description: "Check the event fields and try again." }) });
  return <Section title="Analyze security event" eyebrow="ML DECISION GATE / PERSISTED RESULT" className="mt-5" action={<span className="font-mono text-[10px] text-cyan-300/70">LIVE PIPELINE</span>}><div className="grid gap-5 xl:grid-cols-[1.05fr_0.95fr]"><div className="grid gap-3 sm:grid-cols-2"><label className="block"><span className="mb-2 block font-mono text-[10px] uppercase tracking-[0.16em] text-slate-500">Event pattern</span><select data-testid="dashboard-event-type-select" value={eventType} onChange={(event) => setEventType(event.target.value)} className="h-10 w-full border border-slate-700 bg-[#080f1b] px-3 text-xs text-slate-200 outline-none"><option>Normal Login</option><option>Failed Login Burst</option><option>Port Scan Pattern</option><option>High-volume Traffic</option><option>Suspicious Connection</option><option>Privilege Escalation Indicator</option><option>Data Exfiltration Indicator</option></select></label><label className="block"><span className="mb-2 block font-mono text-[10px] uppercase tracking-[0.16em] text-slate-500">Source IP</span><Input data-testid="dashboard-source-ip-input" value={sourceIp} onChange={(event) => setSourceIp(event.target.value)} className="h-10 rounded-none border-slate-700 bg-[#080f1b] text-xs" /></label><label className="block"><span className="mb-2 block font-mono text-[10px] uppercase tracking-[0.16em] text-slate-500">Failed attempts</span><Input data-testid="dashboard-failed-attempts-input" type="number" min="0" value={failedAttempts} onChange={(event) => setFailedAttempts(event.target.value)} className="h-10 rounded-none border-slate-700 bg-[#080f1b] text-xs" /></label><label className="block"><span className="mb-2 block font-mono text-[10px] uppercase tracking-[0.16em] text-slate-500">Traffic volume</span><Input data-testid="dashboard-traffic-volume-input" type="number" min="0" value={trafficVolume} onChange={(event) => setTrafficVolume(event.target.value)} className="h-10 rounded-none border-slate-700 bg-[#080f1b] text-xs" /></label><Button data-testid="dashboard-analyze-button" type="button" onClick={() => mutation.mutate()} disabled={mutation.isPending} className="h-10 rounded-none bg-cyan-300 font-mono text-[10px] font-semibold tracking-[0.13em] text-[#07111d] hover:bg-cyan-200 sm:col-span-2">{mutation.isPending ? "RUNNING FIVE-AGENT PIPELINE…" : "ANALYZE & PERSIST EVENT"}<ChevronRight size={14} /></Button></div><div className={`flex min-h-[190px] flex-col justify-between border p-5 ${result?.is_threat ? "border-rose-300/40 bg-rose-300/5" : result ? "border-green-300/30 bg-green-300/5" : "border-slate-800 bg-[#080f1b]"}`} data-testid="dashboard-analysis-result"><div className="flex items-start justify-between"><div><div className="font-mono text-[10px] tracking-[0.18em] text-slate-500">DETECTION OUTCOME</div><div className={`mt-3 font-heading text-2xl font-medium tracking-tight ${result?.is_threat ? "text-rose-200" : result ? "text-green-200" : "text-slate-500"}`} data-testid="dashboard-threat-result">{result ? (result.is_threat ? "THREAT PRESENT" : "NO THREAT") : "AWAITING ANALYSIS"}</div></div>{result ? (result.is_threat ? <ShieldAlert className="text-rose-300" size={24} /> : <CheckCircle2 className="text-green-300" size={24} />) : <Gauge className="text-slate-600" size={24} />}</div>{result ? <div className="mt-5 grid grid-cols-3 gap-3 border-t border-slate-700/60 pt-4 font-mono text-[10px]"><div><span className="block text-lg text-slate-100">{result.confidence}%</span><span className="text-slate-600">confidence</span></div><div><span className="block text-lg text-slate-100">{result.risk_score}</span><span className="text-slate-600">risk score</span></div><div><span className="block text-lg text-slate-100">{result.severity}</span><span className="text-slate-600">severity</span></div><p className="col-span-3 border-t border-slate-700/60 pt-3 font-sans text-xs leading-relaxed text-slate-400" data-testid="dashboard-analysis-explanation">{result.explanation}</p></div> : <p className="mt-6 text-xs leading-relaxed text-slate-600">Submit a controlled event. The result is persisted through Monitoring → Detection → Analysis → Decision → Response and appears in the feed, incidents, and audit log.</p>}</div></div><div className="mt-4 border border-yellow-300/20 bg-yellow-300/5 p-3 font-mono text-[10px] uppercase tracking-[0.12em] text-yellow-200/75" data-testid="dashboard-analysis-safety-note"><ShieldCheck size={13} className="mr-2 inline text-yellow-300" /> SAFE_MODE · simulated response only · no external system is modified</div></Section>;
}

function DashboardView({ dashboard, threats, onSelect }: { dashboard?: Dashboard; threats: Threat[]; onSelect: (threat: Threat) => void }) {
  const data = dashboard ?? { total_events: 0, threats_detected: 0, critical_threats: 0, high_threats: 0, active_incidents: 0, simulated_responses: 0, category_distribution: [], severity_distribution: [], timeline: [], simulator: { status: "STOPPED", events_processed: 0, events_per_second: 0.7, threat_probability: 0.48 } };
  return <><PageHeader eyebrow="COMMAND CENTER / OVERVIEW" title="Security Operations Center" subtitle="Real-time threat detection powered by Agentic AI." actions={<div className="flex items-center gap-2 border border-green-300/20 bg-green-300/5 px-3 py-2 font-mono text-[10px] tracking-[0.12em] text-green-300" data-testid="dashboard-live-status"><span className="live-pulse h-1.5 w-1.5 rounded-full bg-green-300" /> LIVE / SAFE MODE</div>} /><div className="grid grid-cols-2 gap-px border border-slate-800 bg-slate-800 lg:grid-cols-6"><Metric label="Total Events" value={data.total_events} detail="All observed activity" icon={Activity} accent="text-cyan-300" /><Metric label="Threats Detected" value={data.threats_detected} detail="ML classified threats" icon={ShieldAlert} accent="text-orange-300" /><Metric label="Critical Threats" value={data.critical_threats} detail="Risk score 76–100" icon={AlertTriangle} accent="text-rose-300" /><Metric label="High Threats" value={data.high_threats} detail="Risk score 51–75" icon={Zap} accent="text-yellow-300" /><Metric label="Active Incidents" value={data.active_incidents} detail="Awaiting resolution" icon={Terminal} accent="text-violet-300" /><Metric label="Simulated Responses" value={data.simulated_responses} detail="SAFE_MODE actions" icon={ShieldCheck} accent="text-green-300" /></div>
    <ThreatAnalyzer /><URLAnalyzer /><div className="mt-5 grid gap-5 xl:grid-cols-[1.4fr_0.8fr]"><Section title="Threats over time" eyebrow="LAST 24 HOURS" className="min-h-[300px]"><div className="h-[220px]" data-testid="dashboard-threats-over-time-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data.timeline}><defs><linearGradient id="cyanFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#22d3ee" stopOpacity={0.3} /><stop offset="100%" stopColor="#22d3ee" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="#1e2d42" strokeDasharray="2 4" vertical={false} /><XAxis dataKey="time" tick={{ fill: "#64748b", fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis allowDecimals={false} tick={{ fill: "#64748b", fontSize: 10 }} axisLine={false} tickLine={false} /><Tooltip contentStyle={tipStyle} /><Area type="monotone" dataKey="threats" stroke="#22d3ee" fill="url(#cyanFill)" strokeWidth={2} /></AreaChart></ResponsiveContainer></div></Section><Section title="Threat categories" eyebrow="CLASSIFIER OUTPUT"><div className="h-[220px]" data-testid="dashboard-category-chart"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={data.category_distribution} innerRadius={58} outerRadius={82} paddingAngle={3} dataKey="value" nameKey="name">{data.category_distribution.map((entry, index) => <Cell key={entry.name} fill={chartColors[index % chartColors.length]} />)}</Pie><Tooltip contentStyle={tipStyle} /><Legend iconType="circle" wrapperStyle={{ fontSize: 10, color: "#94a3b8" }} /></PieChart></ResponsiveContainer></div></Section></div>
    <div className="mt-5 grid gap-5 lg:grid-cols-2"><Section title="Threat severity" eyebrow="CONFIGURABLE RISK BANDS"><div className="h-[220px]" data-testid="dashboard-severity-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={data.severity_distribution}><CartesianGrid stroke="#1e2d42" strokeDasharray="2 4" vertical={false} /><XAxis dataKey="name" tick={{ fill: "#94a3b8", fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis allowDecimals={false} tick={{ fill: "#64748b", fontSize: 10 }} axisLine={false} tickLine={false} /><Tooltip contentStyle={tipStyle} /><Bar dataKey="value" fill="#facc15" radius={[0, 0, 0, 0]} /></BarChart></ResponsiveContainer></div></Section><Section title="Agent activity" eyebrow="MULTI-AGENT PIPELINE"><div className="space-y-3" data-testid="dashboard-agent-activity">{["Monitoring Agent", "Detection Agent", "Analysis Agent", "Decision Agent", "Response Agent"].map((agent, index) => <div key={agent} className="flex items-center gap-3 border-b border-slate-800/70 pb-3 last:border-0 last:pb-0"><div className={`h-2 w-2 ${index === 4 ? "bg-yellow-300" : "bg-cyan-300"}`} /><div className="flex-1 text-xs text-slate-300">{agent}</div><div className="font-mono text-[10px] text-slate-500">{data.total_events} processed</div><CheckCircle2 size={14} className="text-green-300" /></div>)}</div></Section></div>
    <LiveFeed threats={threats} onSelect={onSelect} />
  </>;
}

function LiveFeed({ threats, onSelect }: { threats: Threat[]; onSelect: (threat: Threat) => void }) {
  return <Section title="Live threat feed" eyebrow="REAL-TIME EVENT STREAM" action={<span className="font-mono text-[10px] text-slate-600">{threats.length} RECORDS</span>} className="mt-5"><div className="overflow-x-auto" data-testid="live-threat-feed"><table className="w-full min-w-[760px] text-left"><thead><tr className="border-b border-slate-800 font-mono text-[9px] uppercase tracking-[0.16em] text-slate-600"><th className="pb-3">Time</th><th className="pb-3">Source IP</th><th className="pb-3">Event / Threat</th><th className="pb-3">Confidence</th><th className="pb-3">Risk</th><th className="pb-3">Severity</th><th className="pb-3">Action</th><th className="pb-3">Status</th></tr></thead><tbody>{threats.slice(0, 12).map((threat) => <tr key={threat.id} onClick={() => onSelect(threat)} className="cursor-pointer border-b border-slate-800/60 text-xs hover:bg-cyan-300/5" data-testid={`threat-row-${threat.id}`}><td className="py-3 font-mono text-slate-500">{formatTime(threat.timestamp)}</td><td className="py-3 font-mono text-cyan-200">{threat.event?.source_ip ?? "192.168.1.25"}</td><td className="py-3"><div className="text-slate-300">{threat.event?.event_type ?? threat.prediction}</div><div className="font-mono text-[10px] text-slate-600">{threat.prediction}</div></td><td className="py-3 font-mono text-slate-300">{threat.confidence}%</td><td className="py-3 font-mono text-slate-300">{threat.risk_score}</td><td className="py-3"><Severity value={threat.severity} /></td><td className="py-3 font-mono text-[10px] text-yellow-200/80">{threat.action}</td><td className="py-3"><span className="font-mono text-[10px] text-green-300">{threat.status}</span></td></tr>)}</tbody></table>{threats.length === 0 && <div className="py-12 text-center font-mono text-xs text-slate-600" data-testid="feed-empty-state">NO EVENTS YET · START SAFE SIMULATION TO BEGIN</div>}</div></Section>;
}

function MonitoringView({ dashboard }: { dashboard?: Dashboard }) {
  const [localStatus, setLocalStatus] = useState<string | null>(null);
  const status = localStatus ?? dashboard?.simulator.status ?? "STOPPED";
  const call = useMutation({ mutationFn: (action: string) => apiPost<{ status: string }>(`/simulator/${action}`, action === "start" ? { events_per_second: 0.8, threat_probability: 0.55 } : undefined), onSuccess: (result) => { setLocalStatus(result.status); queryClient.invalidateQueries({ queryKey: ["dashboard"] }); toast.success(`Simulation ${result.status.toLowerCase()}`); }, onError: () => toast.error("Simulator command failed", { description: "The SOC could not change the simulator state." }) });
  return <><PageHeader eyebrow="TELEMETRY / SIMULATOR" title="Live monitoring" subtitle="Synthetic events move through the same production processing pipeline." actions={<div className="flex flex-wrap gap-2"><Button data-testid="simulator-start-button" onClick={() => call.mutate("start")} disabled={status === "RUNNING" || call.isPending} className="rounded-none bg-cyan-300 font-mono text-[10px] text-[#07111d] hover:bg-cyan-200"><Play size={13} /> START</Button><Button data-testid="simulator-pause-button" onClick={() => call.mutate("pause")} disabled={status !== "RUNNING" || call.isPending} variant="outline" className="rounded-none border-slate-700 font-mono text-[10px] text-slate-300"><Pause size={13} /> PAUSE</Button><Button data-testid="simulator-resume-button" onClick={() => call.mutate("resume")} disabled={status !== "PAUSED" || call.isPending} variant="outline" className="rounded-none border-cyan-300/40 font-mono text-[10px] text-cyan-200"><Play size={13} /> RESUME</Button><Button data-testid="simulator-stop-button" onClick={() => call.mutate("stop")} disabled={status === "STOPPED" || call.isPending} variant="outline" className="rounded-none border-rose-400/40 font-mono text-[10px] text-rose-300"><Square size={12} /> STOP</Button></div>} /><div className="grid gap-5 lg:grid-cols-[0.8fr_1.2fr]"><Section title="Simulation control" eyebrow="DEMONSTRATION DATA"><div className="terminal-scan min-h-[280px] bg-[#050a11] p-5 font-mono text-xs" data-testid="simulator-terminal"><div className="mb-6 flex items-center justify-between border-b border-slate-800 pb-3 text-[10px] text-slate-600"><span>cyberguard://simulator</span><span className={status === "RUNNING" ? "text-green-300" : "text-slate-600"}>● {status}</span></div><div className="space-y-3 text-slate-500"><div><span className="text-cyan-300">$</span> mode --safe --synthetic-only</div><div><span className="text-cyan-300">$</span> stream --events-per-second {dashboard?.simulator.events_per_second ?? 0.7}</div><div><span className="text-cyan-300">$</span> threat-probability --value {Math.round((dashboard?.simulator.threat_probability ?? 0.48) * 100)}%</div><div className="pt-4 text-green-300">{status === "RUNNING" ? "> pipeline active / emitting controlled events" : status === "PAUSED" ? "> simulator paused / ready to resume" : "> simulator stopped / ready"}</div><div className="text-slate-700">{"> no external systems are contacted"}</div></div></div></Section><Section title="Pipeline health" eyebrow="PROCESSING TELEMETRY"><div className="grid grid-cols-2 gap-px border border-slate-800 bg-slate-800" data-testid="monitoring-kpis">{[["EVENTS PROCESSED", dashboard?.simulator.events_processed ?? 0], ["EVENTS / SEC", dashboard?.simulator.events_per_second ?? 0.7], ["CURRENT THREAT LEVEL", dashboard?.threats_detected ? "ELEVATED" : "NOMINAL"], ["SAFE MODE", "ENABLED"]].map(([label, value]) => <div key={String(label)} className="bg-[#0c1422] p-4"><div className="font-mono text-[9px] tracking-[0.14em] text-slate-600">{label}</div><div className="mt-3 font-heading text-xl text-slate-100">{value}</div></div>)}</div><div className="mt-5 space-y-2">{["Monitoring Agent", "Detection Agent", "Analysis Agent", "Decision Agent", "Response Agent"].map((agent, index) => <div key={agent} className="flex items-center justify-between border-b border-slate-800/70 py-2 text-xs"><span className="text-slate-400">{agent}</span><span className="flex items-center gap-2 font-mono text-[10px] text-green-300"><span className="h-1.5 w-1.5 rounded-full bg-green-300" />{status === "RUNNING" || index < 2 ? "ACTIVE" : "STANDBY"}</span></div>)}</div></Section></div><div className="mt-5 border border-yellow-300/20 bg-yellow-300/5 p-4 font-mono text-[10px] uppercase tracking-[0.14em] text-yellow-200/80" data-testid="simulation-safety-banner"><ShieldCheck size={14} className="mr-2 inline" /> SIMULATED / DEMONSTRATION DATA · NO MALWARE · NO EXTERNAL SCANNING · NO REAL FIREWALL ACTIONS</div></>;
}

function DeleteHistoryButton({ disabled }: { disabled: boolean }) {
  const mutation = useMutation({ mutationFn: () => apiDelete<{ ok: boolean; deleted: Record<string, number> }>("/detections/history"), onSuccess: (result) => { queryClient.invalidateQueries({ queryKey: ["threats"] }); queryClient.invalidateQueries({ queryKey: ["dashboard"] }); queryClient.invalidateQueries({ queryKey: ["incidents"] }); queryClient.invalidateQueries({ queryKey: ["agents"] }); queryClient.invalidateQueries({ queryKey: ["audit"] }); toast.success("Detection history deleted", { description: `${result.deleted.detections ?? 0} detections and related workflow records were removed from this account.` }); }, onError: () => toast.error("History could not be deleted") });
  return <Button data-testid="delete-detection-history-button" disabled={disabled || mutation.isPending} variant="outline" onClick={() => { if (window.confirm("Delete your detection history, related events, agent executions, incidents, and responses? Audit evidence of this deletion will be retained.")) mutation.mutate(); }} className="rounded-none border-rose-400/40 font-mono text-[10px] text-rose-300 hover:bg-rose-400/10">{mutation.isPending ? "DELETING…" : "DELETE HISTORY"}</Button>;
}

function ThreatsView({ threats, onSelect }: { threats: Threat[]; onSelect: (threat: Threat) => void }) {
  const [query, setQuery] = useState("");
  const filtered = threats.filter((item) => `${item.prediction} ${item.severity} ${item.event?.source_ip ?? ""}`.toLowerCase().includes(query.toLowerCase()));
  return <><PageHeader eyebrow="DETECTION / CLASSIFICATION" title="Threat detection" subtitle="ML predictions and agent decisions captured as an auditable event stream." actions={<div className="flex flex-wrap items-center gap-2"><div className="flex items-center gap-2 border border-slate-800 bg-[#0c1422] px-3"><Search size={14} className="text-slate-600" /><Input data-testid="threat-search-input" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Filter threats…" className="h-9 w-48 rounded-none border-0 bg-transparent text-xs shadow-none" /></div><DeleteHistoryButton disabled={threats.length === 0} /></div>} /><Section title="Detection register" eyebrow="YOUR PRIVATE HISTORY"><div className="mb-4 border border-cyan-300/20 bg-cyan-300/5 p-3 font-mono text-[10px] text-cyan-100/70" data-testid="detection-privacy-note"><LockKeyhole size={13} className="mr-2 inline text-cyan-300" /> Records shown here belong to the current account. Other users cannot read or delete them.</div><div className="overflow-x-auto" data-testid="threat-detection-table"><table className="w-full min-w-[740px] text-left"><thead><tr className="border-b border-slate-800 font-mono text-[9px] tracking-[0.16em] text-slate-600"><th className="pb-3">Threat ID</th><th className="pb-3">Timestamp</th><th className="pb-3">Source</th><th className="pb-3">Attack type</th><th className="pb-3">Confidence</th><th className="pb-3">Risk</th><th className="pb-3">Severity</th><th className="pb-3">Model</th></tr></thead><tbody>{filtered.map((item) => <tr key={item.id} onClick={() => onSelect(item)} className="cursor-pointer border-b border-slate-800/60 text-xs hover:bg-cyan-300/5" data-testid={`detection-table-row-${item.id}`}><td className="py-3 font-mono text-[10px] text-cyan-200">{item.id.slice(0, 10)}…</td><td className="py-3 font-mono text-slate-500">{formatTime(item.timestamp)}</td><td className="py-3 font-mono text-slate-300">{item.event?.source_ip ?? "—"}</td><td className="py-3 text-slate-300">{item.prediction}</td><td className="py-3 font-mono">{item.confidence}%</td><td className="py-3 font-mono">{item.risk_score}</td><td className="py-3"><Severity value={item.severity} /></td><td className="py-3 text-[10px] text-slate-500">Local baseline</td></tr>)}</tbody></table>{filtered.length === 0 && <div className="py-12 text-center font-mono text-xs text-slate-600" data-testid="threat-empty-state">NO MATCHING DETECTIONS</div>}</div></Section></>;
}

function IncidentsView({ incidents }: { incidents: Incident[] }) {
  const [statusOverrides, setStatusOverrides] = useState<Record<string, string>>({});
  const mutation = useMutation({ mutationFn: ({ id, status }: { id: string; status: string }) => apiPatch<Incident>(`/incidents/${id}`, { status }), onMutate: ({ id, status }) => setStatusOverrides((current) => ({ ...current, [id]: status })), onSuccess: (updated) => { queryClient.setQueryData<Incident[]>(["incidents"], (current) => current?.map((incident) => incident.id === updated.id ? updated : incident)); setStatusOverrides((current) => ({ ...current, [updated.id]: updated.status })); queryClient.invalidateQueries({ queryKey: ["incidents"], refetchType: "none" }); toast.success("Incident status updated"); }, onError: (_error, variables) => setStatusOverrides((current) => { const next = { ...current }; delete next[variables.id]; return next; }) });
  return <><PageHeader eyebrow="RESPONSE / CASE MANAGEMENT" title="Incidents" subtitle="Investigate, assign, and resolve high-risk simulated detections." /><Section title="Incident queue" eyebrow="ACTIVE CASES"><div className="space-y-3" data-testid="incident-list">{incidents.map((incident) => <div key={incident.id} className="grid gap-4 border border-slate-800 bg-[#0b1320] p-4 md:grid-cols-[1fr_0.5fr_0.45fr_0.4fr] md:items-center" data-testid={`incident-card-${incident.id}`}><div><div className="font-mono text-[10px] text-cyan-300">INC-{incident.id.slice(0, 7).toUpperCase()}</div><div className="mt-1 text-sm text-slate-200">{incident.title}</div><div className="mt-1 text-xs text-slate-600">Source {incident.source_ip} · assigned to {incident.assigned_to}</div></div><Severity value={incident.severity} /><div className="font-mono text-[10px] text-slate-500">{formatTime(incident.created_at)}</div><select data-testid={`incident-status-select-${incident.id}`} value={statusOverrides[incident.id] ?? incident.status} onChange={(event) => mutation.mutate({ id: incident.id, status: event.target.value })} className="h-8 border border-slate-700 bg-[#080e18] px-2 font-mono text-[10px] text-slate-300 outline-none"><option>OPEN</option><option>INVESTIGATING</option><option>MITIGATED</option><option>RESOLVED</option></select></div>)}{incidents.length === 0 && <div className="py-14 text-center font-mono text-xs text-slate-600" data-testid="incident-empty-state">NO ACTIVE INCIDENTS · SIMULATE A THREAT TO OPEN A CASE</div>}</div></Section></>;
}

function AgentsView({ agents }: { agents: Agent[] }) {
  return <><PageHeader eyebrow="AGENTIC AI / ORCHESTRATION" title="Agent control center" subtitle="Five deterministic agents coordinate analysis and safe response without hidden chain-of-thought." /><div className="mb-5 grid gap-3 border border-slate-800 bg-[#0b1320] p-5 md:grid-cols-5" data-testid="agent-pipeline"><div className="col-span-full mb-2 font-mono text-[10px] tracking-[0.2em] text-slate-600">EVENT RECEIVED → ML MODEL → AGENTIC DECISION → DATABASE</div>{agents.map((agent, index) => <div key={agent.name} className="relative border border-slate-800 bg-[#0c1422] p-4"><div className="flex items-center justify-between"><div className="flex h-8 w-8 items-center justify-center border border-cyan-300/30 bg-cyan-300/10 font-mono text-xs text-cyan-200">0{index + 1}</div><span className="h-1.5 w-1.5 rounded-full bg-green-300" /></div><div className="mt-5 text-xs text-slate-200">{agent.name}</div><div className="mt-2 font-mono text-[10px] leading-relaxed text-slate-600">{agent.purpose}</div><div className="mt-4 flex justify-between border-t border-slate-800 pt-3 font-mono text-[9px] text-slate-500"><span>{agent.events_processed} runs</span><span className="text-green-300">{agent.success_rate}%</span></div>{index < agents.length - 1 && <ChevronRight className="absolute -right-4 top-1/2 z-10 hidden text-yellow-300 md:block" size={16} />}</div>)}</div><Section title="Agent performance" eyebrow="EXECUTION TELEMETRY"><div className="grid gap-3 md:grid-cols-2 lg:grid-cols-5">{agents.map((agent) => <div key={agent.name} className="border border-slate-800 p-4" data-testid={`agent-card-${agent.name.toLowerCase().replaceAll(" ", "-")}`}><div className="flex items-center justify-between"><span className="text-xs text-slate-300">{agent.name.replace(" Agent", "")}</span><Badge variant="outline" className="rounded-none border-green-300/30 text-[9px] text-green-300">{agent.status}</Badge></div><div className="mt-6 font-heading text-2xl text-slate-100">{agent.events_processed}</div><div className="mt-1 text-[10px] text-slate-600">events processed</div><div className="mt-4 grid grid-cols-2 gap-2 border-t border-slate-800 pt-3 font-mono text-[9px] text-slate-500"><div><span className="block text-slate-300">{agent.success_rate}%</span> success</div><div><span className="block text-slate-300">{agent.average_response_time}ms</span> avg time</div></div></div>)}</div></Section></>;
}

function ModelsView({ models }: { models: ModelMetric[] }) {
  const mutation = useMutation({ mutationFn: () => apiPost<{ message: string }>("/models/train"), onSuccess: (result) => toast.success("Candidate evaluation complete", { description: result.message }), onError: () => toast.error("Admin role required") });
  return <><PageHeader eyebrow="MACHINE LEARNING / EVALUATION" title="ML threat detection center" subtitle="Metrics are computed from the deterministic demonstration evaluation set; they are not production benchmarks." actions={<Button data-testid="train-model-button" onClick={() => mutation.mutate()} disabled={mutation.isPending} className="rounded-none bg-yellow-300 font-mono text-[10px] text-[#171207] hover:bg-yellow-200"><RefreshCw size={13} /> {mutation.isPending ? "EVALUATING…" : "TRAIN / EVALUATE"}</Button>} /><div className="mb-5 border border-cyan-300/20 bg-cyan-300/5 p-4 text-xs leading-relaxed text-cyan-100/80" data-testid="model-evaluation-notice"><Database size={15} className="mr-2 inline text-cyan-300" /> Dataset label: <strong>synthetic demonstration evaluation</strong>. Supply NSL-KDD, UNSW-NB15-style, or CICIDS-style CSV data in a future training run before making academic claims.</div><Section title="Model comparison" eyebrow="ACTUAL COMPUTED METRICS"><div className="overflow-x-auto" data-testid="model-comparison-table"><table className="w-full min-w-[780px] text-left"><thead><tr className="border-b border-slate-800 font-mono text-[9px] tracking-[0.16em] text-slate-600"><th className="pb-3">Model</th><th className="pb-3">Accuracy</th><th className="pb-3">Precision</th><th className="pb-3">Recall</th><th className="pb-3">F1</th><th className="pb-3">ROC-AUC</th><th className="pb-3">Train</th><th className="pb-3">Predict</th></tr></thead><tbody>{models.map((model) => <tr key={model.model_name} className="border-b border-slate-800/60 text-xs" data-testid={`model-row-${model.model_name.toLowerCase().replaceAll(" ", "-")}`}><td className="py-4 font-medium text-slate-200">{model.model_name}</td><td className="py-4 font-mono text-cyan-300">{(model.accuracy * 100).toFixed(1)}%</td><td className="py-4 font-mono text-slate-300">{(model.precision * 100).toFixed(1)}%</td><td className="py-4 font-mono text-slate-300">{(model.recall * 100).toFixed(1)}%</td><td className="py-4 font-mono text-slate-300">{(model.f1_score * 100).toFixed(1)}%</td><td className="py-4 font-mono text-slate-300">{(model.roc_auc * 100).toFixed(1)}%</td><td className="py-4 font-mono text-slate-500">{model.training_time_ms}ms</td><td className="py-4 font-mono text-slate-500">{model.prediction_time_ms}ms</td></tr>)}</tbody></table></div></Section></>;
}

function AnalyticsView({ dashboard }: { dashboard?: Dashboard }) {
  const data = dashboard?.severity_distribution ?? [];
  return <><PageHeader eyebrow="OBSERVABILITY / TRENDS" title="Analytics" subtitle="Correlate severity, detection volume, and response posture over time." /><div className="grid gap-5 lg:grid-cols-2"><Section title="Severity trend" eyebrow="CURRENT DATA"><div className="h-[260px]" data-testid="analytics-severity-chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={data}><CartesianGrid stroke="#1e2d42" strokeDasharray="2 4" vertical={false} /><XAxis dataKey="name" tick={{ fill: "#94a3b8", fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis allowDecimals={false} tick={{ fill: "#64748b", fontSize: 10 }} axisLine={false} tickLine={false} /><Tooltip contentStyle={tipStyle} /><Line type="monotone" dataKey="value" stroke="#fb7185" strokeWidth={2} dot={{ fill: "#fb7185", r: 3 }} /></LineChart></ResponsiveContainer></div></Section><Section title="Confidence distribution" eyebrow="MODEL OUTPUT"><div className="h-[260px]" data-testid="analytics-confidence-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={[{ bucket: "<60", count: 0 }, { bucket: "60–75", count: 0 }, { bucket: "75–90", count: 0 }, { bucket: "90+", count: dashboard?.threats_detected ?? 0 }]}><CartesianGrid stroke="#1e2d42" strokeDasharray="2 4" vertical={false} /><XAxis dataKey="bucket" tick={{ fill: "#94a3b8", fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis allowDecimals={false} tick={{ fill: "#64748b", fontSize: 10 }} axisLine={false} tickLine={false} /><Tooltip contentStyle={tipStyle} /><Bar dataKey="count" fill="#a78bfa" /></BarChart></ResponsiveContainer></div></Section></div><div className="mt-5 grid gap-px border border-slate-800 bg-slate-800 sm:grid-cols-3"><div className="bg-[#0c1422] p-5" data-testid="analytics-false-positive-card"><div className="font-mono text-[10px] text-slate-600">FALSE POSITIVES</div><div className="mt-4 font-heading text-2xl text-slate-100">0</div><div className="mt-1 text-xs text-slate-600">feedback not yet labeled</div></div><div className="bg-[#0c1422] p-5" data-testid="analytics-response-card"><div className="font-mono text-[10px] text-slate-600">RESPONSE EFFECTIVENESS</div><div className="mt-4 font-heading text-2xl text-green-300">SAFE</div><div className="mt-1 text-xs text-slate-600">all actions simulated</div></div><div className="bg-[#0c1422] p-5" data-testid="analytics-data-card"><div className="font-mono text-[10px] text-slate-600">DATA QUALITY</div><div className="mt-4 font-heading text-2xl text-cyan-300">DEMO</div><div className="mt-1 text-xs text-slate-600">synthetic records labeled</div></div></div></>;
}

function ReportsView({ report }: { report?: Report }) {
  const download = (type: "csv" | "pdf") => { window.location.assign(`/api/reports/export.${type}`); };
  return <><PageHeader eyebrow="REPORTING / EVIDENCE" title="Security reports" subtitle="Export a concise, auditable view of the safe-mode SOC workflow." actions={<div className="flex gap-2"><Button data-testid="report-export-csv-button" onClick={() => download("csv")} variant="outline" className="rounded-none border-slate-700 font-mono text-[10px] text-slate-300"><Download size={13} /> CSV</Button><Button data-testid="report-export-pdf-button" onClick={() => download("pdf")} className="rounded-none bg-cyan-300 font-mono text-[10px] text-[#07111d] hover:bg-cyan-200"><Download size={13} /> PDF</Button></div>} /><div className="grid gap-5 lg:grid-cols-[1.25fr_0.75fr]"><Section title="Executive summary" eyebrow="GENERATED REPORT"><div className="flex gap-4"><div className="mt-1 text-cyan-300"><FileText size={23} /></div><div><p className="text-sm leading-relaxed text-slate-400" data-testid="report-executive-summary">{report?.executive_summary ?? "Generate activity through the simulator to populate your executive summary."}</p><div className="mt-5 font-mono text-[10px] text-slate-600">Generated {formatTime(report?.generated_at)} · SAFE_MODE ENABLED</div></div></div></Section><Section title="Report sections" eyebrow="CONTENTS"><div className="space-y-3 font-mono text-[10px] text-slate-400" data-testid="report-sections-list">{["Executive Summary", "Event Statistics", "Attack Categories", "Severity Distribution", "ML Performance", "Agent Performance", "Response Actions", "Incident Statistics", "Audit Evidence"].map((item, index) => <div key={item} className="flex items-center justify-between border-b border-slate-800/70 pb-2"><span><span className="mr-3 text-cyan-300/70">0{index + 1}</span>{item}</span><CheckCircle2 size={13} className="text-green-300/70" /></div>)}</div></Section></div><Section title="Report snapshot" eyebrow="BACKEND AGGREGATION" className="mt-5"><div className="grid grid-cols-2 gap-px border border-slate-800 bg-slate-800 sm:grid-cols-4">{[["Events", report?.statistics.total_events ?? 0], ["Threats", report?.statistics.threats_detected ?? 0], ["Incidents", report?.statistics.active_incidents ?? 0], ["Responses", report?.statistics.simulated_responses ?? 0]].map(([label, value]) => <div key={String(label)} className="bg-[#0b1320] p-5"><div className="font-mono text-[10px] text-slate-600">{label}</div><div className="mt-3 font-heading text-2xl text-slate-100">{value}</div></div>)}</div></Section></>;
}

function AuditView({ logs }: { logs: Audit[] }) {
  return <><PageHeader eyebrow="GOVERNANCE / TRACEABILITY" title="Audit logs" subtitle="Security-relevant actions are recorded without passwords or secrets." /><Section title="Activity ledger" eyebrow="IMMUTABLE-STYLE EVENT LOG"><div className="overflow-x-auto" data-testid="audit-log-table"><table className="w-full min-w-[700px] text-left"><thead><tr className="border-b border-slate-800 font-mono text-[9px] tracking-[0.16em] text-slate-600"><th className="pb-3">Timestamp</th><th className="pb-3">User</th><th className="pb-3">Action</th><th className="pb-3">Entity</th><th className="pb-3">Details</th></tr></thead><tbody>{logs.map((log) => <tr key={log.id} className="border-b border-slate-800/60 text-xs" data-testid={`audit-row-${log.id}`}><td className="py-3 font-mono text-slate-500">{formatTime(log.timestamp)}</td><td className="py-3 text-cyan-200">{log.user}</td><td className="py-3 font-mono text-yellow-200/80">{log.action}</td><td className="py-3 text-slate-400">{log.entity}</td><td className="py-3 text-slate-500">{log.details}</td></tr>)}</tbody></table>{logs.length === 0 && <div className="py-12 text-center font-mono text-xs text-slate-600">NO AUDIT EVENTS YET</div>}</div></Section></>;
}

function DatasetsView({ datasets }: { datasets: DatasetRecord[] }) {
  const [file, setFile] = useState<File | null>(null);
  const upload = useMutation({ mutationFn: async () => { if (!file) throw new Error("Select a CSV or TXT file"); const form = new FormData(); form.append("file", file); return apiPost<DatasetRecord>("/datasets/upload", form); }, onSuccess: (dataset) => { queryClient.invalidateQueries({ queryKey: ["datasets"] }); setFile(null); toast.success("Dataset tracked", { description: `${dataset.records.toLocaleString()} records summarized without fitting a production model.` }); }, onError: () => toast.error("Dataset upload failed", { description: "Use a UTF-8 NSL-KDD-style CSV or TXT file under 8 MB." }) });
  return <><PageHeader eyebrow="DATA / PREPROCESSING" title="Dataset management" subtitle="Upload an NSL-KDD-style CSV/TXT file to inspect schema, classes, and preprocessing quality before training." actions={<div className="border border-yellow-300/20 bg-yellow-300/5 px-3 py-2 font-mono text-[10px] text-yellow-200/80" data-testid="dataset-demo-label">DEMONSTRATION DATA STAYS LABELED</div>} /><Section title="Upload controlled dataset" eyebrow="NSL-KDD-STYLE CSV / TXT"><form className="grid gap-4 md:grid-cols-[1fr_auto] md:items-end" data-testid="dataset-upload-form" onSubmit={(event) => { event.preventDefault(); upload.mutate(); }}><label className="block"><span className="mb-2 block font-mono text-[10px] uppercase tracking-[0.16em] text-slate-500">Dataset file</span><Input data-testid="dataset-upload-input" type="file" accept=".csv,.txt,text/csv,text/plain" onChange={(event) => setFile(event.target.files?.[0] ?? null)} className="h-11 rounded-none border-slate-700 bg-[#080f1b] py-2 text-xs text-slate-400 file:mr-3 file:border-0 file:bg-cyan-300/10 file:px-2 file:py-1 file:font-mono file:text-[10px] file:text-cyan-200" /></label><Button data-testid="dataset-upload-button" type="submit" disabled={!file || upload.isPending} className="h-11 rounded-none bg-cyan-300 font-mono text-[10px] text-[#07111d] hover:bg-cyan-200">{upload.isPending ? "PARSING…" : "UPLOAD & PROFILE"}<ArrowUpRight size={14} /></Button></form><div className="mt-4 grid gap-3 text-xs text-slate-500 md:grid-cols-3"><div className="border border-slate-800 bg-[#0b1320] p-3"><div className="font-mono text-[10px] text-cyan-300">01 / SCHEMA</div><div className="mt-2">Header detection, feature count, and preview rows.</div></div><div className="border border-slate-800 bg-[#0b1320] p-3"><div className="font-mono text-[10px] text-cyan-300">02 / QUALITY</div><div className="mt-2">Missing values, categorical columns, and duplicates.</div></div><div className="border border-slate-800 bg-[#0b1320] p-3"><div className="font-mono text-[10px] text-cyan-300">03 / TRACKING</div><div className="mt-2">Classes and records persist in Mongo for later training.</div></div></div></Section><Section title="Tracked datasets" eyebrow="BACKEND DATASET REGISTER" className="mt-5"><div className="space-y-3" data-testid="dataset-register">{datasets.map((dataset) => <div key={dataset.id} className="border border-slate-800 bg-[#0b1320] p-4" data-testid={`dataset-card-${dataset.id}`}><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-start"><div><div className="font-mono text-[10px] text-cyan-300">{dataset.format}</div><h3 className="mt-1 text-sm text-slate-200">{dataset.filename}</h3><div className="mt-1 font-mono text-[10px] text-slate-600">Uploaded {formatTime(dataset.uploaded_at)} · {dataset.is_demo_data ? "DEMONSTRATION DATA" : "SUPPLIED DATA"}</div></div><div className="grid grid-cols-3 gap-5 text-right font-mono text-[10px]"><div><span className="block text-lg text-slate-100">{dataset.records.toLocaleString()}</span><span className="text-slate-600">records</span></div><div><span className="block text-lg text-slate-100">{dataset.features}</span><span className="text-slate-600">features</span></div><div><span className="block text-lg text-slate-100">{dataset.classes.length}</span><span className="text-slate-600">classes</span></div></div></div><div className="mt-4 flex flex-wrap gap-2">{dataset.classes.slice(0, 12).map((item) => <span key={item} className="border border-slate-700 px-2 py-1 font-mono text-[9px] text-slate-400">{item}</span>)}</div><div className="mt-4 grid gap-2 border-t border-slate-800 pt-3 font-mono text-[10px] text-slate-500 sm:grid-cols-4"><span>missing: {dataset.preprocessing.missing_values ?? 0}</span><span>categorical: {dataset.preprocessing.categorical_columns ?? 0}</span><span>duplicates: {dataset.preprocessing.duplicates_detected ?? 0}</span><span>train/test: {dataset.training_records}/{dataset.testing_records}</span></div>{dataset.preview.length > 0 && <details className="mt-4 border-t border-slate-800 pt-3"><summary className="cursor-pointer font-mono text-[10px] text-cyan-300/80" data-testid={`dataset-preview-toggle-${dataset.id}`}>VIEW FIRST {dataset.preview.length} ROWS</summary><pre className="mt-3 max-h-40 overflow-auto bg-[#070c15] p-3 font-mono text-[10px] text-slate-500">{JSON.stringify(dataset.preview, null, 2)}</pre></details>}</div>)}{datasets.length === 0 && <div className="py-14 text-center font-mono text-xs text-slate-600" data-testid="dataset-empty-state">NO UPLOADS YET · SUPPLY NSL-KDD-STYLE CSV/TXT OR USE DEMONSTRATION DATA</div>}</div></Section></>;
}

function SettingsView() {
  const query = useQuery({ queryKey: ["settings"], queryFn: () => apiGet<{ safe_mode: boolean; automatic_simulated_response: boolean; real_time_monitoring: boolean; detection_threshold: number; risk_scoring: string }>("/settings"), retry: false });
  return <><PageHeader eyebrow="CONFIGURATION / POLICY" title="Settings" subtitle="Project controls are explicit, conservative, and safe by default." actions={<DeleteHistoryButton disabled={!query.data} />} /><Section title="System settings" eyebrow="SAFE OPERATING POSTURE"><div className="grid gap-3 md:grid-cols-2">{[["SAFE_MODE", "ENABLED", "All response actions remain simulated."], ["REAL-TIME MONITORING", "ENABLED", "WebSocket event stream is active."], ["AUTO SIMULATED RESPONSE", "ENABLED", "Decision Agent records the safe action."], ["DETECTION THRESHOLD", `${Math.round((query.data?.detection_threshold ?? 0.75) * 100)}%`, "Configurable project threshold."]].map(([label, value, detail]) => <div key={label} className="flex items-center justify-between border border-slate-800 bg-[#0b1320] p-4" data-testid={`setting-${label.toLowerCase().replaceAll(" ", "-")}`}><div><div className="font-mono text-[10px] tracking-[0.12em] text-slate-500">{label}</div><div className="mt-2 text-xs text-slate-600">{detail}</div></div><span className="font-mono text-xs text-cyan-300">{value}</span></div>)}</div><div className="mt-5 border border-yellow-300/20 bg-yellow-300/5 p-4 text-xs leading-relaxed text-yellow-100/75"><AlertTriangle size={15} className="mr-2 inline text-yellow-300" /> Risk scoring is a configurable mechanism for this academic project and is not presented as an industry-standard score.</div></Section></>;
}

function ThreatDrawer({ threat, onClose }: { threat: Threat; onClose: () => void }) {
  const detail = useQuery({ queryKey: ["threat-detail", threat.id], queryFn: () => apiGet<Threat & { agent_executions?: { agent_name: string; status: string; execution_time: number }[] }>(`/detections/${threat.id}`), retry: false });
  return <div className="fixed inset-0 z-50 flex justify-end bg-black/50" data-testid="threat-details-overlay"><button className="absolute inset-0 cursor-default" onClick={onClose} aria-label="Close threat details" data-testid="threat-details-backdrop" /><div className="relative h-full w-full max-w-xl overflow-y-auto border-l border-slate-700 bg-[#0a111d] p-6 shadow-2xl"><div className="flex items-start justify-between border-b border-slate-800 pb-5"><div><div className="font-mono text-[10px] tracking-[0.2em] text-cyan-300">THREAT DETAILS / {threat.id.slice(0, 8)}</div><h2 className="mt-2 font-heading text-2xl text-slate-100">{threat.prediction}</h2></div><button onClick={onClose} className="text-slate-500 hover:text-slate-100" data-testid="threat-details-close-button"><X size={19} /></button></div><div className="mt-6 grid grid-cols-2 gap-px border border-slate-800 bg-slate-800">{[["Confidence", `${threat.confidence}%`], ["Risk score", threat.risk_score], ["Severity", threat.severity], ["Status", threat.status], ["Source", threat.event?.source_ip ?? "—"], ["Protocol", threat.event?.protocol ?? "—"]].map(([label, value]) => <div key={String(label)} className="bg-[#0c1422] p-4"><div className="font-mono text-[9px] text-slate-600">{label}</div><div className="mt-2 text-sm text-slate-200">{value}</div></div>)}</div><div className="mt-6 border border-cyan-300/20 bg-cyan-300/5 p-4"><div className="font-mono text-[10px] tracking-[0.16em] text-cyan-300">SECURITY EXPLANATION</div><p className="mt-3 text-sm leading-relaxed text-slate-300" data-testid="threat-security-explanation">{threat.explanation}</p></div><div className="mt-6"><div className="font-mono text-[10px] tracking-[0.16em] text-slate-600">AGENT TIMELINE</div><div className="mt-3 space-y-2" data-testid="threat-agent-timeline">{(detail.data?.agent_executions ?? ["Monitoring Agent", "Detection Agent", "Analysis Agent", "Decision Agent", "Response Agent"].map((name) => ({ agent_name: name, status: "COMPLETED", execution_time: 0 }))).map((agent) => <div key={agent.agent_name} className="flex items-center justify-between border-b border-slate-800/70 py-3 text-xs"><span className="flex items-center gap-2 text-slate-300"><CheckCircle2 size={14} className="text-green-300" />{agent.agent_name}</span><span className="font-mono text-[10px] text-slate-600">{agent.status} · {agent.execution_time}ms</span></div>)}</div></div><div className="mt-6 border border-yellow-300/20 bg-yellow-300/5 p-4"><div className="font-mono text-[10px] tracking-[0.16em] text-yellow-200">RESPONSE / SAFE_MODE</div><div className="mt-3 flex items-center justify-between"><span className="font-mono text-xs text-slate-300">{threat.action}</span><span className="font-mono text-[10px] text-green-300">SIMULATED / COMPLETED</span></div><p className="mt-3 text-xs leading-relaxed text-slate-500">No firewall, account, endpoint, or external system was modified.</p></div></div></div>;
}

function Shell({ user }: { user: User }) {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [selectedThreat, setSelectedThreat] = useState<Threat | null>(null);
  const location = useLocation();
  const dashboardQuery = useQuery({ queryKey: ["dashboard"], queryFn: () => apiGet<Dashboard>("/dashboard/summary"), refetchInterval: 5000 });
  const threatsQuery = useQuery({ queryKey: ["threats"], queryFn: () => apiGet<Threat[]>("/detections"), refetchInterval: 5000 });
  const incidentsQuery = useQuery({ queryKey: ["incidents"], queryFn: () => apiGet<Incident[]>("/incidents") });
  const agentsQuery = useQuery({ queryKey: ["agents"], queryFn: () => apiGet<Agent[]>("/agents"), refetchInterval: 7000 });
  const modelsQuery = useQuery({ queryKey: ["models"], queryFn: () => apiGet<{ models: ModelMetric[] }>("/models") });
  const datasetsQuery = useQuery({ queryKey: ["datasets"], queryFn: () => apiGet<DatasetRecord[]>("/datasets") });
  const urlChecksQuery = useQuery({ queryKey: ["url-checks"], queryFn: () => apiGet<URLCheck[]>("/url-checks"), refetchInterval: 7000 });
  const reportQuery = useQuery({ queryKey: ["report"], queryFn: () => apiGet<Report>("/reports/summary"), refetchInterval: 7000 });
  const auditQuery = useQuery({ queryKey: ["audit"], queryFn: () => apiGet<Audit[]>("/audit-logs"), refetchInterval: 5000 });
  useEffect(() => { const scheme = window.location.protocol === "https:" ? "wss" : "ws"; const socket = new WebSocket(`${scheme}://${window.location.host}/api/ws/security-events`); let heartbeat: number | undefined; socket.onopen = () => { heartbeat = window.setInterval(() => socket.send("ping"), 20000); }; socket.onmessage = () => { queryClient.invalidateQueries({ queryKey: ["dashboard"] }); queryClient.invalidateQueries({ queryKey: ["threats"] }); queryClient.invalidateQueries({ queryKey: ["incidents"], refetchType: "none" }); queryClient.invalidateQueries({ queryKey: ["agents"] }); }; return () => { if (heartbeat) window.clearInterval(heartbeat); socket.close(); }; }, []);
  const path = location.pathname;
  const content = path === "/monitoring" ? <MonitoringView dashboard={dashboardQuery.data} /> : path === "/threats" ? <ThreatsView threats={threatsQuery.data ?? []} onSelect={setSelectedThreat} /> : path === "/incidents" ? <IncidentsView incidents={incidentsQuery.data ?? []} /> : path === "/agents" ? <AgentsView agents={agentsQuery.data ?? []} /> : path === "/models" ? <ModelsView models={modelsQuery.data?.models ?? []} /> : path === "/datasets" ? <DatasetsView datasets={datasetsQuery.data ?? []} /> : path === "/url-checks" ? <URLChecksView checks={urlChecksQuery.data ?? []} /> : path === "/analytics" ? <AnalyticsView dashboard={dashboardQuery.data} /> : path === "/reports" ? <ReportsView report={reportQuery.data} /> : path === "/audit" ? <AuditView logs={auditQuery.data ?? []} /> : path === "/settings" ? <SettingsView /> : <DashboardView dashboard={dashboardQuery.data} threats={threatsQuery.data ?? []} onSelect={setSelectedThreat} />;
  return <div className="flex min-h-svh bg-[#070c15] text-slate-100"><Sidebar open={sidebarOpen} onClose={() => setSidebarOpen(false)} user={user} /><div className="min-w-0 flex-1"><Topbar onMenu={() => setSidebarOpen(true)} user={user} /><main className="soc-grid min-h-[calc(100vh-76px)] p-4 sm:p-7" data-testid="soc-main-content">{content}</main></div>{selectedThreat && <ThreatDrawer threat={selectedThreat} onClose={() => setSelectedThreat(null)} />}</div>;
}

export default function Home() {
  const sessionHint = window.localStorage.getItem("cyberguard-session-hint") === "true";
  const meQuery = useQuery({ queryKey: ["me"], queryFn: () => apiGet<User>("/auth/me"), retry: false, enabled: sessionHint });
  return meQuery.data ? <Shell user={meQuery.data} /> : <AuthGate />;
}